import json


def extract_qa_pairs(data):
    """
    从通话记录中提取QA对

    参数:
        data: 原始JSON数据

    返回:
        QA对列表
    """
    records = data['data']['records']
    qa_pairs = []
    current_robot_question = None
    current_node = None

    # for record in records:
    for idx, record in enumerate(records):
        notify = record.get('notify')

        # 处理机器人发言
        # 1. notify == "enter" 时，机器人开场
        if notify == 'enter':
            robot_text = ""
            node_name = record.get('answer_text', '')

            # 从 contents 中提取文本
            if record.get('contents'):
                robot_text = ' '.join([c['translate_text'] for c in record['contents']])
            elif record.get('answer_content'):
                content = record['answer_content']
                lines = content.split('\n')
                robot_text = '\n'.join([line for line in lines if not line.strip().endswith('秒')])

            # 清理文本
            robot_text = robot_text.strip()
            if ':' in robot_text:
                parts = robot_text.split(':', 1)
                if parts[0] in ['Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'Q6', 'Q7', 'Q1-A', 'Q1-default']:
                    robot_text = parts[1].strip()

            current_robot_question = robot_text
            current_node = node_name

        # 2. notify == "asrmessage_notify" 时，可能包含用户回答和机器人新问题
        elif notify == 'asrmessage_notify':
            # 先处理用户回答（如果存在）
            if record.get('question'):
                user_answer = record['question'].strip()

                # 提取tags
                tags_list = []
                if record.get('tags'):
                    tags_list = [tag['name'] for tag in record['tags']]
                tags_str = ','.join(tags_list) if tags_list else ''

                # 关键：检查 answer_content 是否为 null
                # 如果为 null，说明用户继续说话，需要合并到上一个QA对
                if record.get('answer_text') is None:
                    # 合并逻辑：找到最后一个相同节点的QA对，合并用户回答
                    if qa_pairs and current_node:
                        last_qa = qa_pairs[-1]
                        # 检查最后一个QA对是否是当前节点
                        if current_node in last_qa:
                            # 合并用户回答
                            last_qa[current_node]['custom'] += ',' + user_answer
                            # 更新tags（如果新的有tags）
                            if tags_str:
                                last_qa['tags'] = tags_str
                        else:
                            # 如果节点不同，创建新QA对
                            if current_robot_question:
                                qa_pairs.append({
                                    current_node: {
                                        "robot": current_robot_question,
                                        "custom": user_answer
                                    },
                                    "tags": tags_str
                                })
                else:
                    # answer_content 不为 null，创建新的QA对
                    if current_robot_question and current_node:
                        if len(qa_pairs) <= 0:
                            qa_pairs.append({
                                current_node: {
                                    "robot": current_robot_question,
                                    "custom": user_answer
                                },
                                "tags": tags_str
                            })
                        else:
                            last_qa = qa_pairs[-1]
                            # 检查最后一个QA对是否是当前节点
                            if current_node in last_qa:
                                # 合并用户回答
                                last_qa[current_node]['custom'] += ',' + user_answer
                                # 更新tags（如果新的有tags）
                                if tags_str:
                                    last_qa['tags'] = tags_str
                            else:
                                # 如果节点不同，创建新QA对
                                if current_robot_question:
                                    qa_pairs.append({
                                        current_node: {
                                            "robot": current_robot_question,
                                            "custom": user_answer
                                        },
                                        "tags": tags_str
                                    })

            # 再处理机器人新问题（如果存在）
            if record.get('answer_content'):
                robot_text = ""
                node_name = record.get('answer_text', '')
                if "Q" not in node_name:
                    contents = record['contents']
                    for content in contents:
                        if "Q" in content['translate_text']:
                            node_name = content['translate_text'].split(":")[0]
                            break

                # 从 contents 中提取文本
                if record.get('contents'):
                    robot_text = ' '.join([c['translate_text'] for c in record['contents']])
                else:
                    content = record['answer_content']
                    lines = content.split('\n')
                    robot_text = '\n'.join([line for line in lines if not line.strip().endswith('秒')])

                # 清理文本
                robot_text = robot_text.strip()
                if ':' in robot_text:
                    parts = robot_text.split(':', 1)
                    if parts[0] in ['Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'Q6', 'Q7', 'Q1-A', 'Q1-default']:
                        robot_text = parts[1].strip()

                current_robot_question = robot_text
                current_node = node_name
            if idx == len(records) - 1:
                # 处理最后一条记录，如果是用户回答但没有对应的机器人问题
                if current_robot_question and current_node:
                    tags_list = []

                    tags_str = ','.join(tags_list) if tags_list else ''
                    qa_pairs.append({
                        current_node: {
                            "robot": current_robot_question,
                            "custom": ""
                        },
                        "tags": ""
                    })
    return qa_pairs



def format_qa_output(qa_pairs):
    """格式化输出QA对"""
    print(json_str)
    print("=" * 60)
    print("通话QA对提取结果")
    print("=" * 60)
    
    for i, qa in enumerate(qa_pairs, 1):
        # 获取节点名称和tags
        node_name = None
        tags = qa.get('tags', '')
        
        for key in qa:
            if key != 'tags':
                node_name = key
                content = qa[key]
                break
        
        if node_name:
            print(f"\n【轮次 {i} - {node_name}】")
            print(f"机器人: {content['robot']}")
            print(f"用户:   {content['custom']}")
            print(f"标签:   {tags if tags else '无'}")
            print("-" * 60)
    
    return qa_pairs

def qa_pairs_to_user_text_and_labels(
                                    qa_pairs: list[dict[str, Any]],
                                         ) -> tuple[str, list[str]]:
    user_text: list[str] = []
    asr_labels: list[str] = []
    META_KEYS = {"tags", "notify"}

    # 1) 解析 qa_pairs
    for item in qa_pairs:
        # tags → labels
        tags_str = (item.get("tags") or "").strip()
        if tags_str:
            for t in tags_str.split(","):
                t = t.strip()
                if t:
                    asr_labels.append(t)

        # custom → user_text
        for k, v in item.items():
            if k in META_KEYS:
                continue
            custom = (v or {}).get("custom", "")
            custom = (custom or "").strip()
            if custom:
                user_text.append(custom)

    return " ".join(user_text), asr_labels


# 示例使用
if __name__ == "__main__":
    # 这里放你的JSON数据
    json_data = json_str
    
    # 解析JSON
    data = json.loads(json_data)
    
    # 提取QA对
    result_map: dict[str, dict] = {}
    qa_pairs = extract_qa_pairs(data)
    user_text, asr_labels = qa_pairs_to_user_text_and_labels(qa_pairs)
    result_map["callid"] = {
        "user_text": user_text,
        "asr_labels": asr_labels,
    }
    # 格式化输出
    format_qa_output(qa_pairs)
    
    # 输出为JSON格式
    print("\nJSON格式输出:")
    print(json.dumps(qa_pairs, ensure_ascii=False, indent=2))
    print(result_map)